/* imported theme CSS — scoped to .wpdev-theme-page (site nav/footer/hero stay KodRank) */

.wpdev-theme-page{
  --ink:#0A1A22;
  --ink-2:#0F2A33;
  --ink-3:#163B44;
  --signal:#F47A1F;
  --signal-deep:#CD661A;
  --signal-ink:#0A1A22;
  --beam:#F6A54E;
  --paper:#FFFFFF;
  --mist:#F1F5F3;
  --mist-2:#E8EFEB;
  --line:#E1E9E5;
  --line-dark:rgba(244,122,31,.16);
  --graphite:#0D2029;
  --slate:#4B5B62;
  --slate-2:#6B7A80;

  --shadow-sm:0 1px 2px rgba(13,32,41,.05),0 6px 18px -8px rgba(13,32,41,.10);
  --shadow-md:0 2px 4px rgba(13,32,41,.05),0 18px 40px -20px rgba(13,32,41,.22);

  --pad:clamp(18px,3.2vw,40px);
  --max:1560px;
}
.wpdev-theme-page *, .wpdev-theme-page *::before, .wpdev-theme-page *::after{box-sizing:border-box;margin:0;padding:0;font-family:inherit}
.wpdev-theme-page{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
.wpdev-theme-page{
  font-family:"Poppins",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  font-weight:400;font-size:16px;line-height:1.6;
  color:var(--graphite);background:var(--paper);
  -webkit-font-smoothing:antialiased;
}
.wpdev-theme-page img, .wpdev-theme-page svg{display:block;max-width:100%;height:auto}
.wpdev-theme-page a{color:inherit;text-decoration:none}
.wpdev-theme-page button{font-family:inherit;cursor:pointer;border:none;background:none}
.wpdev-theme-page ::selection{background:var(--signal);color:var(--ink)}
.wpdev-theme-page .wrap{max-width:var(--max);margin:0 auto;padding:0 var(--pad)}
.wpdev-theme-page section{padding:clamp(44px,7vw,100px) 0;position:relative}
.wpdev-theme-page .sec-ink{background:var(--ink);color:#B7CBD2}
.wpdev-theme-page .sec-mist{background:var(--mist)}
.wpdev-theme-page .sec-paper{background:var(--paper)}
.wpdev-theme-page h1, .wpdev-theme-page h2, .wpdev-theme-page h3, .wpdev-theme-page h4{font-family:inherit;line-height:1.15;letter-spacing:-.01em;color:var(--graphite)}
.wpdev-theme-page h1{font-weight:800;font-size:clamp(2.2rem,5.2vw,4.1rem);letter-spacing:-.025em}
.wpdev-theme-page h2{font-weight:700;font-size:clamp(1.75rem,3.6vw,2.65rem);letter-spacing:-.02em}
.wpdev-theme-page h3{font-weight:650;font-size:clamp(1.15rem,1.8vw,1.45rem)}
.wpdev-theme-page h4{font-weight:600;font-size:1.05rem}
.wpdev-theme-page p{color:var(--slate);font-size:1rem;line-height:1.7}
.wpdev-theme-page .sec-ink h1, .wpdev-theme-page .sec-ink h2, .wpdev-theme-page .sec-ink h3, .wpdev-theme-page .sec-ink h4{color:#fff}
.wpdev-theme-page .sec-ink p{color:#9FB6BE}
.wpdev-theme-page .sec-ink .lede{color:#9FB6BE}
.wpdev-theme-page .sec-ink .body-2{color:#B7CBD2}
.wpdev-theme-page .eyebrow{
  font-size:.75rem;font-weight:500;letter-spacing:.08em;text-transform:uppercase;
  color:var(--signal-deep);display:inline-block;margin-bottom:18px;
}
.wpdev-theme-page .sec-ink .eyebrow{color:var(--signal)}
.wpdev-theme-page .eyebrow::before{content:"— ";margin-right:2px}
.wpdev-theme-page .hl{color:var(--signal-deep);font-weight:600}
.wpdev-theme-page .sec-ink .hl{color:var(--signal)}
.wpdev-theme-page strong{font-weight:650;color:var(--graphite)}
.wpdev-theme-page .sec-ink strong{color:#fff}
.wpdev-theme-page .btn{
  display:inline-flex;align-items:center;gap:9px;padding:14px 24px;
  font-weight:600;font-size:.95rem;border-radius:999px;
  transition:all .25s ease;border:1px solid transparent;white-space:nowrap;cursor:pointer;
}
.wpdev-theme-page .btn svg{width:16px;height:16px;transition:transform .25s ease}
.wpdev-theme-page .btn:hover svg{transform:translateX(4px)}
.wpdev-theme-page .btn-primary{background:var(--signal);color:var(--signal-ink)}
.wpdev-theme-page .btn-primary:hover{background:#F69750;transform:translateY(-1px);box-shadow:var(--shadow-sm)}
.wpdev-theme-page .btn-ghost-light{background:rgba(255,255,255,.05);color:#fff;border-color:rgba(255,255,255,.28);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.wpdev-theme-page .btn-ghost-light:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.5)}
.wpdev-theme-page .btn-ghost-dark{background:#fff;color:var(--graphite);border-color:var(--line)}
.wpdev-theme-page .btn-ghost-dark:hover{border-color:var(--graphite)}
.wpdev-theme-page .btn-ink{background:var(--ink);color:#fff}
.wpdev-theme-page .btn-ink:hover{background:#16323D}
.wpdev-theme-page .btn-sm{padding:10px 18px;font-size:.875rem}
.wpdev-theme-page .nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.85);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.wpdev-theme-page .nav-inner{display:flex;align-items:center;justify-content:space-between;padding:16px 0;gap:32px}
.wpdev-theme-page .logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:1.25rem;color:var(--graphite)}
.wpdev-theme-page .logo-mark{width:32px;height:32px;border-radius:8px;background:linear-gradient(135deg,var(--signal) 0%,var(--signal-deep) 100%);display:grid;place-items:center;color:var(--ink);font-weight:800;font-size:1rem}
.wpdev-theme-page .nav-links{display:flex;align-items:center;gap:28px;list-style:none}
.wpdev-theme-page .nav-links a{font-weight:600;font-size:.9rem;color:var(--graphite);transition:color .2s}
.wpdev-theme-page .nav-links a:hover{color:var(--signal-deep)}
.wpdev-theme-page .nav-cta{display:flex;align-items:center;gap:12px}
.wpdev-theme-page .nav-toggle{display:none;width:40px;height:40px;border-radius:8px;background:var(--mist);align-items:center;justify-content:center}
.wpdev-theme-page .nav-toggle span{width:18px;height:2px;background:var(--graphite);position:relative}
.wpdev-theme-page .nav-toggle span::before, .wpdev-theme-page .nav-toggle span::after{content:"";position:absolute;left:0;width:18px;height:2px;background:var(--graphite)}
.wpdev-theme-page .nav-toggle span::before{top:-6px}
.wpdev-theme-page .nav-toggle span::after{top:6px}
@media(max-width:960px){.nav-links,.nav-cta .btn:not(.btn-primary){display:none}
.wpdev-theme-page .nav-toggle{display:flex}}
.wpdev-theme-page .hero{background:var(--ink);color:#fff;padding:0;overflow:hidden;position:relative;min-height:min(760px,92vh)}
.wpdev-theme-page .hero-grid{display:block;padding:clamp(24px,3.5vw,48px) 0 clamp(56px,7vw,104px);width:100%}
.wpdev-theme-page .hero-copy{padding:0;max-width:none;position:relative;z-index:3}
.wpdev-theme-page .breadcrumb{margin-bottom:28px}
.wpdev-theme-page .breadcrumb ol{display:flex;flex-wrap:wrap;align-items:center;gap:10px;list-style:none;font-size:.8rem;font-weight:500;letter-spacing:.04em}
.wpdev-theme-page .breadcrumb li{display:flex;align-items:center;gap:10px}
.wpdev-theme-page .breadcrumb li:not(:last-child)::after{content:"›";color:#5A6E77;font-size:1rem;font-weight:400;line-height:1}
.wpdev-theme-page .breadcrumb a{color:#B7CBD2;transition:color .2s ease}
.wpdev-theme-page .breadcrumb a:hover{color:var(--signal)}
.wpdev-theme-page .breadcrumb [aria-current="page"]{color:var(--signal);font-weight:600}
.wpdev-theme-page .hero h1{color:#fff;font-size:clamp(2.35rem,6.4vw,4.1rem);line-height:1.08;letter-spacing:-.03em;font-weight:800;margin:24px 0 28px;max-width:640px;text-shadow:0 2px 24px rgba(0,0,0,.35)}
.wpdev-theme-page .hero h1 .accent{color:var(--signal);display:inline}
.wpdev-theme-page .hero .lede{font-size:clamp(1.05rem,1.4vw,1.22rem);line-height:1.6;color:#B7CBD2;margin-bottom:30px;max-width:560px;text-shadow:0 2px 16px rgba(0,0,0,.3)}
.wpdev-theme-page .hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:36px}
.wpdev-theme-page .hero-badges{display:flex;flex-wrap:wrap;gap:22px 40px;padding-top:24px;border-top:1px solid rgba(255,255,255,.12);max-width:940px}
.wpdev-theme-page .hero-badge{display:flex;flex-direction:column;gap:2px}
.wpdev-theme-page .hero-badge .num{font-size:2rem;font-weight:800;color:var(--signal);line-height:1;letter-spacing:-.02em}
.wpdev-theme-page .hero-badge .lbl{font-size:.72rem;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:#8FA5AD;margin-top:10px}
.wpdev-theme-page .hero-visual{position:absolute;inset:0;z-index:1;height:100%;min-height:100%;overflow:hidden;pointer-events:none}
.wpdev-theme-page .hero-visual::before{
  content:"";position:absolute;inset:0;z-index:2;
  
  background:linear-gradient(95deg,
    rgba(10,26,34,1) 0%,
    rgba(10,26,34,.96) 10%,
    rgba(10,26,34,.82) 22%,
    rgba(10,26,34,.58) 34%,
    rgba(10,26,34,.34) 46%,
    rgba(10,26,34,.15) 58%,
    rgba(10,26,34,.04) 68%,
    rgba(10,26,34,0) 78%);
  pointer-events:none;
}
.wpdev-theme-page .hero-visual::after{
  content:"";position:absolute;inset:0;z-index:2;
  
  background:linear-gradient(180deg,rgba(10,26,34,.32) 0%,rgba(10,26,34,0) 16%,rgba(10,26,34,0) 80%,rgba(10,26,34,.5) 100%);
  pointer-events:none;
}
.wpdev-theme-page .hero-img{width:100%;height:100%;object-fit:cover;object-position:right center;position:absolute;inset:0;opacity:1}

@media(max-width:820px){
  .hero{min-height:auto}
.wpdev-theme-page .hero-grid{padding:88px 0 64px}
.wpdev-theme-page .hero-badges{gap:22px 32px}
.wpdev-theme-page .hero-badge .num{font-size:1.5rem}
.wpdev-theme-page .hero h1{font-size:clamp(2.1rem,9vw,3.2rem);line-height:1.12}
.wpdev-theme-page .hero-visual::before{
    background:linear-gradient(180deg,
      rgba(10,26,34,.92) 0%,
      rgba(10,26,34,.8) 36%,
      rgba(10,26,34,.5) 58%,
      rgba(10,26,34,.28) 74%,
      rgba(10,26,34,.5) 100%);
  }
.wpdev-theme-page .hero-visual::after{display:none}
}
.wpdev-theme-page .trust{background:var(--paper);padding:clamp(32px,4.5vw,52px) 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.wpdev-theme-page .trust-inner{display:flex;align-items:center;justify-content:space-between;gap:32px;flex-wrap:wrap}
.wpdev-theme-page .trust-label{font-size:.75rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--slate-2)}
.wpdev-theme-page .trust-logos{display:flex;align-items:center;gap:clamp(20px,3vw,48px);flex-wrap:wrap;opacity:.65}
.wpdev-theme-page .trust-logo{font-weight:700;font-size:.9rem;color:var(--slate);letter-spacing:.02em}
.wpdev-theme-page .section-head{max-width:820px;margin:0 0 clamp(24px,4vw,40px);text-align:left}
.wpdev-theme-page .section-head p{margin-top:16px;font-size:1.05rem}
.wpdev-theme-page .problem-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:0}
@media(max-width:980px){.problem-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.problem-grid{grid-template-columns:1fr}}
.wpdev-theme-page .problem-card{background:var(--ink-2);border:1px solid var(--line-dark);border-radius:18px;padding:clamp(24px,3vw,30px) clamp(22px,2.5vw,26px);position:relative;transition:all .3s ease}
.wpdev-theme-page .problem-card:hover{border-color:rgba(244,122,31,.4);transform:translateY(-2px)}
.wpdev-theme-page .problem-card .icon{width:44px;height:44px;border-radius:12px;background:rgba(244,122,31,.12);display:grid;place-items:center;margin-bottom:18px}
.wpdev-theme-page .problem-card .icon svg{width:22px;height:22px;stroke:var(--signal);fill:none;stroke-width:1.75}
.wpdev-theme-page .problem-card h4{color:#fff;margin-bottom:10px;font-size:1.02rem}
.wpdev-theme-page .problem-card p{font-size:.9rem;color:#9FB6BE;line-height:1.6}
.wpdev-theme-page .service-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}
.wpdev-theme-page .svc-card{background:var(--paper);border-radius:18px;padding:clamp(24px,3vw,30px) clamp(22px,2.5vw,26px);border:1px solid var(--line);position:relative;transition:all .3s ease;display:flex;flex-direction:column}
.wpdev-theme-page .svc-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md);border-color:transparent}
.wpdev-theme-page .svc-card .tile{width:52px;height:52px;border-radius:12px;background:var(--mist);display:grid;place-items:center;transition:background .25s ease;margin-bottom:20px}
.wpdev-theme-page .svc-card:hover .tile{background:var(--signal)}
.wpdev-theme-page .svc-card .tile svg{width:26px;height:26px;stroke:var(--graphite);fill:none;stroke-width:1.75;transition:stroke .25s ease}
.wpdev-theme-page .svc-card:hover .tile svg{stroke:var(--signal-ink)}
.wpdev-theme-page .svc-card .check{position:absolute;top:24px;right:24px;width:26px;height:26px;border-radius:50%;background:var(--signal);color:var(--signal-ink);display:grid;place-items:center;font-size:.75rem;font-weight:700}
.wpdev-theme-page .svc-card h3{margin-bottom:10px;font-weight:650;font-size:1.15rem}
.wpdev-theme-page .svc-card p{font-size:.9rem;flex:1;margin-bottom:0}
.wpdev-theme-page .feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
@media(max-width:980px){.feature-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.feature-grid{grid-template-columns:1fr}}
.wpdev-theme-page .feat-card{background:var(--ink-2);border:1px solid var(--line-dark);border-radius:18px;padding:clamp(26px,3.2vw,32px) clamp(22px,2.8vw,28px);transition:all .3s ease;position:relative}
.wpdev-theme-page .feat-card:hover{border-color:rgba(244,122,31,.35);background:var(--ink-3)}
.wpdev-theme-page .feat-card .ic{width:48px;height:48px;border-radius:12px;background:rgba(244,122,31,.14);display:grid;place-items:center;margin-bottom:20px}
.wpdev-theme-page .feat-card .ic svg{width:24px;height:24px;stroke:var(--signal);fill:none;stroke-width:1.75}
.wpdev-theme-page .feat-card h3{color:#fff;font-size:1.1rem;margin-bottom:10px}
.wpdev-theme-page .feat-card p{font-size:.9rem;color:#B7CBD2}
.wpdev-theme-page .sec-ink.why-bg{position:relative;isolation:isolate;overflow:hidden}
.wpdev-theme-page .sec-ink.why-bg::before{
  content:"";position:absolute;inset:0;z-index:-2;
  background:url('data:image/png;base64,') center 30%/cover no-repeat;
}
.wpdev-theme-page .sec-ink.why-bg::after{
  content:"";position:absolute;inset:0;z-index:-1;
  
  background:
    linear-gradient(100deg,rgba(10,26,34,.92) 0%,rgba(10,26,34,.74) 24%,rgba(10,26,34,.46) 44%,rgba(10,26,34,.22) 64%,rgba(10,26,34,.34) 100%),
    linear-gradient(180deg,rgba(10,26,34,.52) 0%,rgba(10,26,34,.18) 30%,rgba(10,26,34,.06) 68%,rgba(10,26,34,.16) 100%);
}
.wpdev-theme-page .sec-ink.why-bg .feat-card{
  background:rgba(15,42,51,.74);
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  border-color:rgba(244,122,31,.18);
}
.wpdev-theme-page .sec-ink.why-bg .feat-card:hover{background:rgba(22,59,68,.82)}
.wpdev-theme-page .sec-ink.stats-bg{position:relative;isolation:isolate;overflow:hidden}
.wpdev-theme-page .sec-ink.stats-bg::before{
  content:"";position:absolute;inset:0;z-index:-2;
  background:url('data:image/jpeg;base64,') center right/cover no-repeat;
}
.wpdev-theme-page .sec-ink.stats-bg::after{
  content:"";position:absolute;inset:0;z-index:-1;
  
  background:
    linear-gradient(100deg,rgba(10,26,34,.88) 0%,rgba(10,26,34,.7) 26%,rgba(10,26,34,.44) 48%,rgba(10,26,34,.24) 68%,rgba(10,26,34,.34) 100%),
    linear-gradient(180deg,rgba(10,26,34,.18) 0%,rgba(10,26,34,.42) 20%,rgba(10,26,34,.42) 80%,rgba(10,26,34,.18) 100%);
}
.wpdev-theme-page .sec-ink.stats-bg .stat{border-left-color:rgba(255,255,255,.15)}

@media(max-width:820px){
  .sec-ink.why-bg::after{
    background:
      linear-gradient(180deg,rgba(10,26,34,.86) 0%,rgba(10,26,34,.62) 34%,rgba(10,26,34,.34) 62%,rgba(10,26,34,.5) 100%);
  }
.wpdev-theme-page .sec-ink.stats-bg::after{
    background:linear-gradient(180deg,rgba(10,26,34,.85) 0%,rgba(10,26,34,.55) 32%,rgba(10,26,34,.4) 68%,rgba(10,26,34,.72) 100%);
  }
}
.wpdev-theme-page .process-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:0}
.wpdev-theme-page .proc{background:var(--paper);border-radius:18px;padding:clamp(24px,3vw,28px) clamp(22px,2.5vw,24px);border:1px solid var(--line);border-top:2px solid var(--signal);position:relative;transition:all .3s ease}
.wpdev-theme-page .proc:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.wpdev-theme-page .proc .num{font-size:2.5rem;font-weight:800;color:var(--signal);line-height:1;letter-spacing:-.03em;margin-bottom:18px;display:block}
.wpdev-theme-page .proc h4{font-size:1.05rem;font-weight:650;margin-bottom:8px}
.wpdev-theme-page .proc p{font-size:.9rem}
.wpdev-theme-page .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:24px;margin-top:0}
.wpdev-theme-page .stat{padding:16px 0;border-left:1px solid rgba(255,255,255,.08);padding-left:22px}
.wpdev-theme-page .stat:first-child{border-left:none;padding-left:0}
.wpdev-theme-page .stat .num{font-size:clamp(2.3rem,4vw,3rem);font-weight:800;line-height:1;letter-spacing:-.03em;color:#fff;display:block;margin-bottom:10px}
.wpdev-theme-page .stat .num.signal{color:var(--signal)}
.wpdev-theme-page .stat .lbl{font-size:.72rem;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:#7A929A}
.wpdev-theme-page .compare-wrap{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:0}
.wpdev-theme-page .compare-card{background:var(--ink-2);border-radius:18px;padding:clamp(28px,3vw,32px) clamp(22px,2.5vw,28px);border:1px solid var(--line-dark)}
.wpdev-theme-page .compare-card.pro{border:2px solid var(--signal);background:var(--ink);position:relative}
.wpdev-theme-page .compare-card.pro::before{content:"KodRank";position:absolute;top:-14px;left:32px;background:var(--signal);color:var(--signal-ink);padding:5px 14px;border-radius:999px;font-size:.72rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.wpdev-theme-page .compare-card h3{color:#fff;font-size:1.1rem;margin-bottom:22px;font-weight:650}
.wpdev-theme-page .compare-card.muted h3{color:#9FB6BE}
.wpdev-theme-page .compare-list{list-style:none;display:flex;flex-direction:column;gap:13px}
.wpdev-theme-page .compare-list li{font-size:.9rem;color:#B7CBD2;padding-left:30px;position:relative;line-height:1.55}
.wpdev-theme-page .compare-list li .mark{position:absolute;left:0;top:2px;width:19px;height:19px;border-radius:50%;display:grid;place-items:center;font-size:.68rem;font-weight:700}
.wpdev-theme-page .compare-list li .mark.x{background:rgba(255,80,80,.12);color:#FF7676}
.wpdev-theme-page .compare-list li .mark.v{background:var(--signal);color:var(--signal-ink)}
.wpdev-theme-page .compare-card.muted li{color:#9FB6BE}
@media(max-width:820px){.compare-wrap{grid-template-columns:1fr}}
.wpdev-theme-page .why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
@media(max-width:980px){.why-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.why-grid{grid-template-columns:1fr}}
.wpdev-theme-page .why-card{background:var(--ink);border-radius:18px;padding:clamp(26px,3.2vw,32px) clamp(22px,3vw,28px);color:#fff;border:1px solid rgba(255,255,255,.06);transition:all .3s ease}
.wpdev-theme-page .why-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md);border-color:rgba(244,122,31,.3)}
.wpdev-theme-page .why-card .tile{width:48px;height:48px;border-radius:12px;background:rgba(244,122,31,.14);display:grid;place-items:center;margin-bottom:18px}
.wpdev-theme-page .why-card .tile svg{width:22px;height:22px;stroke:var(--signal);fill:none;stroke-width:1.75}
.wpdev-theme-page .why-card h3{color:#fff;font-size:1.05rem;margin-bottom:8px}
.wpdev-theme-page .why-card p{font-size:.875rem;color:#9FB6BE;margin-bottom:0}
.wpdev-theme-page .testi-wrap{margin-top:0}
.wpdev-theme-page .testi-track{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none;padding-bottom:4px}
.wpdev-theme-page .testi-track::-webkit-scrollbar{display:none}
.wpdev-theme-page .testi{flex:0 0 clamp(280px,42vw,420px);scroll-snap-align:start;background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:clamp(24px,3vw,28px);display:flex;flex-direction:column}
.wpdev-theme-page .testi .stars{display:flex;gap:3px;margin-bottom:16px}
.wpdev-theme-page .testi .stars svg{width:15px;height:15px;fill:var(--signal);stroke:none}
.wpdev-theme-page .testi p{font-size:.925rem;color:var(--graphite);line-height:1.65;margin-bottom:20px;flex:1}
.wpdev-theme-page .testi-person{display:flex;align-items:center;gap:12px}
.wpdev-theme-page .testi-avatar{width:42px;height:42px;border-radius:50%;background:linear-gradient(135deg,var(--signal),var(--signal-deep));display:grid;place-items:center;color:#fff;font-weight:700;font-size:.85rem}
.wpdev-theme-page .testi-name{font-weight:650;font-size:.9rem}
.wpdev-theme-page .testi-role{font-size:.8rem;color:var(--slate-2)}
.wpdev-theme-page .testi-controls{display:flex;gap:10px;margin-top:24px}
.wpdev-theme-page .testi-nav{width:40px;height:40px;border-radius:50%;border:1px solid var(--line);display:grid;place-items:center;transition:all .2s}
.wpdev-theme-page .testi-nav:hover:not(:disabled){background:var(--ink);border-color:var(--ink)}
.wpdev-theme-page .testi-nav:hover:not(:disabled) svg{stroke:#fff}
.wpdev-theme-page .testi-nav svg{width:16px;height:16px;stroke:var(--graphite);fill:none;stroke-width:2.2}
.wpdev-theme-page .testi-nav:disabled{opacity:.3;cursor:default}
.wpdev-theme-page .faq-list{max-width:820px;margin-top:0;display:flex;flex-direction:column;gap:10px}
.wpdev-theme-page .faq-item{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:6px 22px;transition:border-color .2s}
.wpdev-theme-page .faq-item[open]{border-color:rgba(244,122,31,.35)}
.wpdev-theme-page .faq-item summary{list-style:none;cursor:pointer;padding:18px 0;display:flex;align-items:center;justify-content:space-between;gap:16px;font-weight:650;font-size:1rem;color:var(--graphite)}
.wpdev-theme-page .faq-item summary::-webkit-details-marker{display:none}
.wpdev-theme-page .faq-toggle{flex-shrink:0;color:var(--signal-deep);font-size:1.3rem;font-weight:400;transition:transform .2s}
.wpdev-theme-page .faq-item[open] .faq-toggle{transform:rotate(45deg)}
.wpdev-theme-page .faq-body{padding:0 0 22px;font-size:.925rem;color:var(--slate);line-height:1.7}
.wpdev-theme-page .cta-band{text-align:center;max-width:760px;margin:0 auto;position:relative;z-index:2}
.wpdev-theme-page .cta-band .btn{margin-top:8px}
.wpdev-theme-page .sec-ink.cta-bg{position:relative;isolation:isolate;overflow:hidden}
.wpdev-theme-page .sec-ink.cta-bg::before{
  content:"";position:absolute;inset:0;z-index:-2;
  background:url('data:image/png;base64,') center 38%/cover no-repeat;
}
.wpdev-theme-page .sec-ink.cta-bg::after{
  content:"";position:absolute;inset:0;z-index:-1;
  background:
    radial-gradient(62% 130% at 50% 50%,rgba(10,26,34,.94) 0%,rgba(10,26,34,.84) 42%,rgba(10,26,34,.56) 68%,rgba(10,26,34,.3) 100%),
    linear-gradient(90deg,rgba(10,26,34,.22) 0%,rgba(10,26,34,.08) 14%,rgba(10,26,34,.18) 55%,rgba(10,26,34,.6) 78%,rgba(10,26,34,.74) 100%),
    linear-gradient(180deg,rgba(10,26,34,.35) 0%,rgba(10,26,34,.05) 25%,rgba(10,26,34,.05) 75%,rgba(10,26,34,.4) 100%);
}

@media(max-width:820px){
  .sec-ink.cta-bg::after{
    background:
      radial-gradient(90% 120% at 50% 45%,rgba(10,26,34,.92) 0%,rgba(10,26,34,.82) 50%,rgba(10,26,34,.6) 100%),
      linear-gradient(180deg,rgba(10,26,34,.4) 0%,rgba(10,26,34,.15) 30%,rgba(10,26,34,.6) 100%);
  }
}
.wpdev-theme-page .contact-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:44px;align-items:start}
@media(max-width:900px){.contact-grid{grid-template-columns:1fr}}
.wpdev-theme-page .contact-side h2{margin-bottom:16px}
.wpdev-theme-page .contact-side p{margin-bottom:32px}
.wpdev-theme-page .contact-meta{display:flex;flex-direction:column;gap:20px}
.wpdev-theme-page .cm-item{display:flex;align-items:center;gap:14px}
.wpdev-theme-page .cm-icon{width:40px;height:40px;border-radius:10px;background:var(--paper);border:1px solid var(--line);display:grid;place-items:center;flex-shrink:0}
.wpdev-theme-page .cm-icon svg{width:18px;height:18px;stroke:var(--signal-deep);fill:none;stroke-width:1.8}
.wpdev-theme-page .cm-item .label{font-size:.72rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--slate-2)}
.wpdev-theme-page .cm-item .value{font-weight:600;font-size:.95rem;margin-top:2px}
.wpdev-theme-page .contact-card{background:var(--paper);border-radius:18px;padding:clamp(28px,3.5vw,36px);box-shadow:var(--shadow-md)}
.wpdev-theme-page .form-row{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.wpdev-theme-page .form-field{display:flex;flex-direction:column;gap:8px}
.wpdev-theme-page .form-field.full{grid-column:1/-1}
.wpdev-theme-page .form-field label{font-size:.8rem;font-weight:600;color:var(--graphite)}
.wpdev-theme-page .form-field input, .wpdev-theme-page .form-field select, .wpdev-theme-page .form-field textarea{
  border:none;border-bottom:1.5px solid var(--line);padding:10px 2px;font-size:.95rem;
  background:transparent;color:var(--graphite);transition:border-color .2s;font-family:inherit;
}
.wpdev-theme-page .form-field input:focus, .wpdev-theme-page .form-field select:focus, .wpdev-theme-page .form-field textarea:focus{outline:none;border-color:var(--signal)}
.wpdev-theme-page .form-field textarea{resize:vertical}
.wpdev-theme-page .form-submit{margin-top:26px;width:100%;justify-content:center}
@media(max-width:560px){.form-row{grid-template-columns:1fr}}